  },
}));

const allItems = $input.all();
const results = [];

for (const item of allItems) {
  const files = item.json.files || [];

  for (const f of files) {
    const folderId = Array.isArray(f.parents) ? f.parents[0] : null;

    results.push({
      json: {
        fileId: f.id,
        fileName: f.name,
        mimeType: f.mimeType,
        folderId,          // important
      },
    });
  }
}

return results;

