// On récupère la moyenne (Mean) de la luminosité (ici sur le canal Red pour l'exemple)
const mean = $json["Channel Statistics"].Red.Mean.match(/\(([^)]+)\)/)[1]; // Extrait 0.6444
const stdDev = $json["Channel Statistics"].Red["Standard Deviation"].match(/\(([^)]+)\)/)[1]; // Extrait l'écart-type

let brightnessBoost = 100; // 100 = pas de changement
let contrastCommand = "";

// LOGIQUE LUMINOSITÉ (On veut atteindre 0.75)
if (mean < 0.70) {
    // Si trop sombre, on calcule le boost (ex: 0.75 / 0.64 * 100 = 117)
    brightnessBoost = Math.round((0.75 / mean) * 100);
}

// LOGIQUE CONTRASTE (On veut au moins 0.22)
if (stdDev < 0.15) {
    contrastCommand = "+contrast +contrast +contrast"; // Fort boost
} else if (stdDev < 0.20) {
    contrastCommand = "+contrast"; // Boost léger
}

return {
    brightnessBoost,
    contrastCommand,
    originalMean: mean,
    originalStdDev: stdDev
};

