// 1. Récupération des infos de l'item actuel (JSON uniquement)
const item = $input.item.json;

// 2. Récupération du nom du dossier parent (Ex: "EKS00005144 - Blanchi Oltre")
// On pointe vers le nœud ancêtre qui contient le nom du dossier
const folderName = $('Split_out_sources_folders').item.json.name || "";

// 3. Extraction des 11 premiers caractères (Le SKU)
const extractedSku = folderName.substring(0, 11);

// 4. Récupération de TOUS les produits Magento pour trouver le match
const magentoItems = $('GET_MAGENTO_PRODUCTS').all();
const product = magentoItems.find(p => p.json.sku === extractedSku);

// 5. Préparation des variables
let brand = "inconnue";
let model = "modele-inconnu";
let millesime = "2026";
let errorMsg = null;

if (product) {
    brand = product.json.ekstere_brand || "marque";
    model = product.json.ekstere_model || "modele";
    millesime = product.json.ekstere_year || "2026";
} else {
    errorMsg = `SKU ${extractedSku} non trouvé dans Magento`;
}

// 6. Construction d'une suggestion de nom de fichier (slugify léger)
const cleanString = (str) => {
    return str.toLowerCase()
              .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
              .replace(/[^a-z0-9]/g, '-')
              .replace(/-+/g, '-')
              .replace(/^-|-$/g, '');
};

const photoIndex = ($input.item.index || 0) + 1;
const skuSuffix = extractedSku.slice(-4);
const finalFileNameBase = `ekstere-${cleanString(brand)}-${cleanString(model)}-${skuSuffix}-${photoIndex}`;

// 7. Retour du résultat
return {
    sku_extracted: extractedSku,
    folder_original_name: folderName,
    brand: brand,
    model: model,
    millesime: millesime,
    suggestedFileName: finalFileNameBase,
    error: errorMsg,
    original_item_info: item // On conserve les infos du fichier (id, name drive, etc.)
};
